register = template.Library()

@register.tag
def gravatar_url(parser, token):
    """
    Returns the URL of the gravatar for the email passed in.
    If no email is found, returns the url for the missing-gravatar image.
    """
    args = token.split_contents()
    if len(args) != 2:
        raise template.TemplateSyntaxError("'gravatar_url' tag requires exactly one argument")
    return GravatarUrlNode(Variable(args[1]))

class GravatarUrlNode(Node):
    def __init__(self, email_var):
        self.email_var = email_var
    def render(self, context):
        try:
            email = self.email_var.resolve(context)
        except VariableDoesNotExist:
            email = ""
        md5 = hashlib.md5(email.lower()).hexdigest()
        return "http://www.gravatar.com/avatar/%s" % (md5)

@register.tag
defodu(parser, token):
    """
    The tag evaluates the variable passed and, if it is a model instance,
    renders it using the template path "<app_label>/<model_name>.html".
    """
    args = token.split_contents()
    if len(args) != 2:
        raise template.TemplateSyntaxError("'odu' tag requires exactly one argument")
    return OduNode(Variable(args[1]))

class OduNode(Node):
    def __init__(self, var):
        self.var = var
    def render(self, context):
        obj = self.var.resolve(context)
        if not isinstance(obj, models.Model):
            raise template.TemplateSyntaxError("You must pass in a model instance")
        t = get_template("%s/%s.html" % (obj._meta.app_label, obj._meta.model_name))
        c = template.Context(context)
        c.push(obj)
        return t.render(c)

